import type { Request } from 'express';
import type { REQUEST_METADATA_PROPERTY } from '../tokens/request-processing.tokens.js';

/**
 * What the logging middleware records about a request and what
 * `@RequestMetadata()` hands to a controller. Exactly these four fields, and
 * nothing else (no headers, no cookies, no body): the object is returned to
 * API clients by `GET /tasks/request-info`.
 */
export interface RequestMetadataInfo {
  /** Unique per request, generated by the server (never taken from the client). */
  requestId: string;
  /** When the middleware saw the request. */
  startedAt: Date;
  /** Client IP as Express reports it; `undefined` when it is unknown. */
  clientIp: string | undefined;
  /** The `User-Agent` header; `undefined` when the client sent none. */
  userAgent: string | undefined;
}

/** An Express request after the middleware ran (`requestMetadata` is set). */
export type RequestWithMetadata = Request & {
  [K in typeof REQUEST_METADATA_PROPERTY]?: RequestMetadataInfo;
};
